# -*- coding: utf-8 -*-
# (speaker, french, korean); speaker None => stage direction (not a turn)
H, L, J, V = "Hélène", "Lucien", "Julien", "Victor"
D = [
(None, "Jeudi 17 décembre, 15 h 10. Le service de midi est fini, la salle sent encore la peinture fraîche. Sur l'ardoise : « Merci à vous 1 237. » Hélène vérifie des bons de livraison au comptoir, Lucien boit son café, Julien essuie des verres.", "12월 17일 목요일 오후 3시 10분. 점심 영업은 끝났지만 홀에는 아직 새 페인트 냄새가 난다. 칠판에는 « 후원해 주신 1,237분께 감사드립니다. » 엘렌은 카운터에서 납품서를 확인하고, 뤼시앵은 커피를 마시고, 쥘리앵은 잔을 닦는다."),
(J, "Mme Vasseur est repartie ravie. Elle a dit que la peinture était « acceptable ».", "바세르 부인은 아주 만족해서 돌아가셨어. 페인트가 \"봐줄 만하다\"고 하시더라."),
(H, "« Acceptable » ? Chez elle, c'est une médaille d'or.", "\"봐줄 만하다\"? 그분한테는 금메달이나 마찬가지지."),
(L, "Trente ans à la table sept, elle a le droit d'être difficile. L'essentiel, c'est qu'elle soit revenue.", "7번 테이블에서 30년이면 까다로울 자격이 있지. 중요한 건 돌아왔다는 거야."),
(H, "Jeudi, steak-frites, Henri qui dit rien. On dirait que rien n'a changé.", "목요일, 스테이크 프리트, 말 한마디 없는 앙리. 아무것도 안 변한 것 같네."),
(J, "Sauf le plafond. Et le chiffre sur l'ardoise : mille deux cent trente-sept.", "천장만 빼고. 그리고 칠판의 숫자도. 1,237."),
(L, "Mille deux cent trente-sept personnes ont mis la main au portefeuille pour nous. On n'oublie pas ça.", "1,237명이 우리를 위해 지갑을 열었어. 그건 잊으면 안 돼."),
(H, "Je l'oublie pas, Papa. Je le relis chaque matin en écrivant le menu.", "안 잊어요, 아빠. 매일 아침 메뉴 쓸 때 다시 읽는걸요."),
(None, "On frappe à la vitrine. Dehors, un homme en manteau sombre tient une bouteille et fait un petit signe de la main.", "유리문을 두드리는 소리. 밖에서 어두운 코트를 입은 남자가 병을 들고 작게 손짓한다."),
(J, "Euh... Hélène ? Quelqu'un frappe à la porte. Et je crois que tu le connais.", "음... 엘렌? 누가 문을 두드리는데. 아는 사람일 것 같아."),
(H, "On est fermés jusqu'à dix-neuf heures. Il sait lire, non ?", "저녁 7시까지 휴업이야. 글자는 읽을 줄 알겠지?"),
(J, "C'est Victor Lambert. Avec une bouteille et un grand sourire.", "빅토르 랑베르야. 병 하나랑 함박웃음을 들고."),
(L, "Un voisin qui arrive avec un cadeau, méfie-toi. Souviens-toi du cheval de Troie.", "선물 들고 오는 이웃은 조심해라. 트로이의 목마를 떠올려 봐."),
(H, "Papa, ici c'est la rue Saint-Maur, pas Troie. Julien, ouvre-lui.", "아빠, 여긴 트로이가 아니라 생모르 거리예요. 쥘리앵, 열어 줘."),
(J, "Bonjour, monsieur Lambert. Entrez, vous allez prendre froid.", "안녕하세요, 랑베르 씨. 들어오세요, 감기 걸리겠어요."),
(V, "Merci, Julien. Bonjour, Lucien. Bonjour, Hélène. Je vous dérange en plein creux de l'après-midi, je sais.", "고마워요, 쥘리앵. 안녕하세요, 뤼시앵. 안녕하세요, 엘렌. 한창 쉬는 오후 시간에 방해하는 거 알아요."),
(H, "Un peu, oui. Livreurs, factures, peinture qui sèche... Vous avez cinq minutes, pas plus.", "조금요. 배달, 청구서, 마르는 페인트... 5분이에요, 그 이상은 안 돼요."),
(V, "Cinq minutes me suffiront. Tenez, c'est pour la réouverture : un savagnin du Jura.", "5분이면 충분해요. 자, 재개점 선물이에요. 쥐라 지방 사바냥이에요."),
(H, "C'est gentil. Mais je ne sais pas encore ce que vous voulez en échange.", "고마워요. 그런데 그 대가로 뭘 원하시는지 아직 모르겠네요."),
(V, "Rien. Enfin, si : cinq minutes. Mais la bouteille est gratuite, je vous le jure.", "아무것도요. 아니, 있긴 하네요. 5분. 그래도 병은 공짜예요, 맹세해요."),
(L, "Au moins, il est honnête. Posez ça sur le comptoir, jeune homme. Un café ?", "적어도 정직하군. 그건 카운터에 올려놓게, 젊은이. 커피 한잔?"),
(None, "Lucien sert une tasse à Victor, qui reste debout près de la porte, son manteau toujours sur les épaules.", "뤼시앵이 빅토르에게 잔을 건넨다. 빅토르는 코트를 걸친 채 문 가까이에 서 있다."),
(V, "Avec plaisir. C'est toujours la même machine ? Elle date de Marthe, non ?", "고맙습니다. 아직 그 기계예요? 마르트 때부터 있던 거죠?"),
(L, "Mêmes tuyaux, même mauvais caractère. Comme ma fille.", "같은 배관, 같은 고약한 성질. 내 딸처럼."),
(H, "Papa !", "아빠!"),
(V, "Je le prends comme un compliment. Elle est belle, votre salle. Plus claire, plus calme.", "칭찬으로 받아들일게요. 홀이 예쁘네요. 더 밝고 더 차분해졌어요."),
(H, "Elle n'a jamais été aussi propre. Avant, les murs jaunes faisaient cuisine de grand-mère.", "이렇게 깨끗한 적이 없었죠. 예전엔 노란 벽 때문에 할머니 부엌 같았거든요."),
(V, "Et ce chêne, derrière l'ardoise ? Il est magnifique.", "그리고 칠판 뒤의 저 참나무는요? 정말 근사해요."),
(J, "C'est monsieur Lopes qui l'a posé, la veille de la réouverture. Il a travaillé jusqu'à minuit.", "로페스 씨가 재개점 전날 달았어요. 자정까지 일했죠."),
(V, "Beau travail. Et ce chiffre, en bas : « 1 237 ». Ce sont les gens qui vous ont aidés ?", "훌륭한 솜씨네요. 그리고 아래쪽 이 숫자, « 1,237 ». 도와준 분들 수예요?"),
(H, "Oui. Chaque nom est sur une liste, sous la caisse. Je les connais presque tous.", "네. 이름은 하나하나 계산대 밑 명단에 있어요. 거의 다 기억해요."),
(V, "Alors vous ne trouverez pas le mien. J'ai donné quarante euros, en cochant « anonyme ».", "그럼 제 이름은 못 찾으실 거예요. 40유로를 냈는데 \"익명\"에 체크했거든요."),
(H, "Vous avez... Pardon ? Vous avez participé à la collecte ?", "당신이... 뭐라고요? 모금에 참여했다고요?"),
(L, "Ça alors. Un concurrent qui finance la concurrence.", "이런. 경쟁자가 경쟁자 돈을 대 주다니."),
(V, "Ce n'est pas de la charité, Lucien. C'est de l'intérêt bien compris. Je vais vous expliquer.", "자선이 아니에요, 뤼시앵. 현명한 이해타산이죠. 설명해 드릴게요."),
(H, "J'écoute. Mais vous restez debout : vous avez dit cinq minutes.", "들을게요. 하지만 서 계세요. 5분이라고 하셨잖아요."),
(V, "Parfait. J'ai deux propositions. La première, ce sont des achats groupés.", "좋아요. 제안이 두 가지 있어요. 첫째는 공동 구매예요."),
(H, "Des achats groupés ? Avec vous ? Pour quoi faire ?", "공동 구매요? 당신이랑요? 뭘 위해서요?"),
(V, "Pour le beurre, les œufs, la farine et l'huile. J'ai appelé Bastide hier.", "버터, 달걀, 밀가루, 기름이요. 어제 바스티드에게 전화했어요."),
(H, "Vous avez appelé Bastide sans me prévenir ?", "나한테 말도 없이 바스티드한테 전화했다고요?"),
(V, "Exprès. Je voulais savoir si c'était possible avant de vous embêter.", "일부러요. 귀찮게 해 드리기 전에 가능한 일인지 먼저 알고 싶었어요."),
(J, "Et il a dit quoi, Bastide ? D'habitude, il en dit beaucoup.", "바스티드가 뭐래요? 평소엔 말이 많은 분인데."),
(V, "Que les producteurs pourraient livrer davantage, si on commandait à deux.", "우리가 둘이 같이 주문하면 생산자들이 더 많이 납품할 수 있을 거라고요."),
(H, "Mes producteurs. Ceux du contrat de novembre. Ils ont signé avec moi, pas avec vous.", "내 생산자들이에요. 11월 계약을 맺은 분들이죠. 나랑 서명했지, 당신이랑 한 게 아니에요."),
(V, "Je sais. Je ne veux rien leur prendre. Je veux ajouter mes volumes aux vôtres.", "알아요. 그분들에게서 뭘 뺏으려는 게 아니에요. 제 물량을 당신 물량에 더하려는 거예요."),
(V, "Je prends cent vingt kilos de beurre par mois. Vous, quarante, c'est ça ?", "저는 한 달에 버터를 120킬로 써요. 당신은 40킬로, 맞죠?"),
(H, "À peu près. Vous êtes bien renseigné.", "대충요. 정보가 빠르시네요."),
(V, "À cent soixante kilos, le producteur descend de onze euros à neuf euros soixante le kilo.", "160킬로가 되면 생산자가 킬로당 11유로에서 9유로 60센트로 내려요."),
(J, "Un euro quarante de moins au kilo. Sur quarante kilos, ça fait cinquante-six euros par mois.", "킬로당 1유로 40센트 싸지네. 40킬로면 한 달에 56유로야."),
(L, "Cinquante-six euros ! Pour ça, on vend son âme ?", "56유로! 그걸로 영혼을 팔아?"),
(J, "Ça fait quand même six cent soixante-douze euros par an, Lucien. Rien que pour le beurre.", "그래도 1년이면 672유로예요, 뤼시앵. 버터만 해서."),
(H, "Et avec les œufs, la farine, l'huile ? Ça fait combien en tout ?", "달걀, 밀가루, 기름까지 하면요? 전부 얼마죠?"),
(V, "Pour vous, entre mille et mille deux cents euros par an. Pour moi, bien plus. Je ne vais pas mentir.", "당신은 1년에 1,000에서 1,200유로쯤. 저는 훨씬 더 많고요. 거짓말은 안 할게요."),
(H, "Voilà. Vous gagnez plus que moi. C'est ça, votre « intérêt bien compris ».", "그렇군요. 당신이 나보다 더 벌어요. 그게 당신의 \"현명한 이해타산\"이네요."),
(V, "Oui. Je gagne plus que vous, et vous gagnez quand même. C'est du donnant-donnant.", "맞아요. 저는 당신보다 더 벌고, 당신도 어쨌든 벌어요. 주고받기죠."),
(H, "Et mes producteurs ? Si vous tirez les prix vers le bas, ils vont me le reprocher.", "내 생산자들은요? 당신이 가격을 끌어내리면 나를 원망할 텐데요."),
(V, "Ils vendront plus. Ils perdent un peu au kilo, mais ils gagnent cent vingt kilos par mois.", "더 많이 팔게 돼요. 킬로당은 조금 손해지만 한 달에 120킬로를 더 팔잖아요."),
(H, "C'est le raisonnement de quelqu'un qui n'a jamais eu un producteur furieux au téléphone.", "화난 생산자와 전화해 본 적 없는 사람의 논리네요."),
(V, "Détrompez-vous. Mon ancien fournisseur m'a lâché en pleine saison. J'ai compris la leçon.", "오해예요. 예전 납품업자가 한창 성수기에 저를 버렸어요. 교훈은 얻었죠."),
(L, "Remarquez, ne pas mettre tous ses œufs dans le même panier, ça se défend.", "하긴, 달걀을 한 바구니에 다 담지 말라는 말도 일리는 있지."),
(V, "C'est mon argument, Lucien. Là, vous auriez deux paniers, et moi aussi.", "제 논리가 그거예요, 뤼시앵. 그러면 당신도 바구니가 둘, 저도 둘이죠."),
(H, "Mes conditions, alors. Ce sont les producteurs qui décident. Pas vous, pas moi.", "그럼 내 조건이에요. 결정은 생산자들이 해요. 당신도 나도 아니고요."),
(V, "D'accord. S'ils veulent me rencontrer, j'irai avec vous à la ferme.", "좋아요. 그분들이 저를 만나고 싶어 하면 같이 농장에 갈게요."),
(H, "Et chacun paie sa facture à soixante jours. Pas de mélange des comptes.", "그리고 각자 자기 청구서를 60일 안에 내요. 장부를 섞지 않는 거예요."),
(V, "Chacun ses comptes. Je signe pour douze mois, comme vous.", "각자 장부는 각자. 저도 당신처럼 12개월로 서명할게요."),
(H, "Je n'ai pas dit oui. J'ai dit : mes conditions.", "승낙한 게 아니에요. 내 조건이라고 했을 뿐이죠."),
(V, "Je traduis : « peut-être », très poliment.", "통역하면, 아주 정중한 \"어쩌면\"이네요."),
(J, "Chez Hélène, un « peut-être » poli, c'est un oui qui n'ose pas encore.", "엘렌한테 정중한 \"어쩌면\"은 아직 용기를 못 낸 \"좋아요\"예요."),
(H, "Et la deuxième proposition ? Je sens qu'elle est pire.", "두 번째 제안은요? 더 나쁠 것 같은 예감이 드는데."),
(V, "Elle est plus fragile. Je voudrais une soirée à deux, un samedi de février.", "더 조심스러운 제안이에요. 2월의 어느 토요일에 둘이 함께하는 저녁이요."),
(V, "Un dîner croisé : apéritif et entrée chez moi, le plat chez vous, le dessert chez moi.", "교차 만찬이에요. 식전주와 앙트레는 우리 집, 메인은 당신 집, 디저트는 다시 우리 집."),
(H, "Le plat principal chez moi... Vous me donnez le beau rôle. Pourquoi ?", "메인 요리가 우리 쪽이라... 나한테 좋은 역할을 주네요. 왜죠?"),
(V, "Parce que votre blanquette est la meilleure du quartier. Tout le monde le sait.", "당신의 블랑케트가 동네 최고니까요. 모두 알아요."),
(H, "Ne me flattez pas. Ça marche rarement.", "아첨하지 마세요. 잘 안 통해요."),
(V, "Je ne flatte pas, je constate. Mon plat du jour est moins bon que le vôtre, mais il coûte moins cher.", "아첨이 아니라 사실을 말하는 거예요. 제 오늘의 요리는 당신 것보다 맛은 덜하지만 값은 싸죠."),
(J, "Quarante convives à quarante-huit euros, tout compris : ça fait mille neuf cent vingt euros à partager.", "손님 40명에 인당 48유로, 전부 포함이면 1,920유로를 나누게 되네요."),
(V, "Voilà. Mille neuf cent vingt euros en deux, et surtout deux salles pleines en février.", "맞아요. 1,920유로를 둘이 나누고, 무엇보다 2월에 홀 두 곳이 가득 차죠."),
(L, "Février, c'est le mois creux. Sur ce point, il a raison.", "2월은 한산한 달이지. 그 점은 이 친구 말이 맞아."),
(H, "Et mes habitués chez vous ? Ils verront vos prix, plus bas que les miens, et ils ne reviendront plus.", "내 단골들이 당신 가게에 가면요? 나보다 싼 가격을 보고 다시는 안 올 텐데요."),
(V, "Ou ils verront que votre assiette est plus généreuse que la mienne, et ils reviendront chez vous.", "아니면 당신 접시가 제 것보다 푸짐하다는 걸 보고 당신한테 다시 올 거예요."),
(V, "Les gens comparent, Hélène. Mais ils n'ont qu'un ventre, ils ne dînent pas deux fois.", "사람들은 비교하죠, 엘렌. 하지만 배는 하나라서 저녁을 두 번 먹지는 않아요."),
(H, "Pourquoi maintenant ? Pourquoi pas en septembre, quand on était à terre ?", "왜 하필 지금이죠? 우리가 바닥에 있던 9월은 왜 아니었고요?"),
(V, "En septembre, vous aviez fermé. Ma salle était pleine, et la rue était morte.", "9월엔 문을 닫으셨죠. 제 홀은 찼는데 거리는 죽어 있었어요."),
(V, "Je n'aimais pas ça. Un restaurant tout seul dans une rue vide, ça tient mal.", "그게 싫었어요. 텅 빈 거리에 식당 하나만 있으면 버티기 힘들어요."),
(J, "Une rue qui vit attire du monde. Il n'a pas tort, Hélène.", "활기 있는 거리는 사람을 끌죠. 틀린 말은 아니야, 엘렌."),
(H, "Ça, c'est le côté calcul. Et le côté sincère ? Il y en a un, non ?", "그건 계산 쪽이고요. 진심 쪽은요? 있긴 하죠, 안 그래요?"),
(V, "Oui. À dix-neuf ans, votre mère m'a pris comme plongeur. Un mois d'été.", "있어요. 열아홉 살 때 어머님이 저를 설거지 담당으로 써 주셨어요. 여름 한 달 동안이요."),
(V, "Je cassais trois assiettes par jour. Elle me répétait toujours la même phrase.", "저는 하루에 접시를 세 개씩 깼어요. 어머님은 늘 같은 말씀을 하셨죠."),
(L, "« On ne cuisine pas contre quelqu'un, on cuisine pour quelqu'un. » Je l'entends encore.", "\"누구에 맞서 요리하는 게 아니야, 누군가를 위해 요리하는 거지.\" 지금도 들리는구먼."),
(H, "Elle me l'a dite aussi. J'avais dix ans, je pleurais parce qu'une copine avait gagné le concours de gâteaux.", "나한테도 하셨어요. 열 살 때, 친구가 케이크 대회에서 이겼다고 울었거든요."),
(L, "Elle la disait à tout le monde. Même au facteur.", "누구한테나 했지. 우체부한테도."),
(V, "Vous voyez : je n'ai rien inventé. J'ai juste mis vingt ans à comprendre.", "보세요, 제가 지어낸 게 아니에요. 이해하는 데 20년 걸렸을 뿐이죠."),
(H, "Ne jouez pas la carte de ma mère, Victor. C'est déloyal.", "우리 엄마 카드를 쓰지 마세요, 빅토르. 비겁해요."),
(V, "Vous avez raison, pardon. Je retire. Gardez le calcul, oubliez Marthe.", "맞아요, 죄송해요. 취소할게요. 계산은 남기고 마르트는 잊으세요."),
(H, "Non, je ne l'oublie pas. Je dis juste que ça ne suffit pas pour signer.", "아니요, 잊지 않아요. 서명하기엔 그걸로 부족하다는 말이에요."),
(L, "Voilà ma fille. Il a plaidé, elle a pesé. Maintenant elle va trancher.", "그게 내 딸이지. 저쪽은 변론했고 이쪽은 저울질했어. 이제 결정할 차례야."),
(H, "Achats groupés : trois mois d'essai, pas douze. Beurre et farine d'abord, à condition que les producteurs soient d'accord.", "공동 구매는 석 달 시험이에요, 열두 달 말고. 버터와 밀가루부터, 생산자들이 동의한다는 조건으로."),
(V, "Trois mois, ça me va. Et les producteurs, vous les appelez ou je les appelle ?", "석 달이면 좋아요. 생산자들한테는 당신이 전화해요, 제가 할까요?"),
(H, "Je les appelle. Ce sont mes producteurs, j'ai promis de ne rien décider sans eux.", "내가 해요. 내 생산자들이고, 그분들 없이는 아무것도 결정하지 않겠다고 약속했으니까."),
(V, "Très bien. Et le dîner croisé ?", "좋아요. 교차 만찬은요?"),
(H, "Je ne réponds pas aujourd'hui. Je veux d'abord voir les chiffres de janvier.", "오늘은 대답 안 해요. 먼저 1월 숫자를 보고 싶어요."),
(J, "Réponse après le Nouvel An. C'est raisonnable, non ?", "새해 지나고 대답한다. 합리적이잖아요?"),
(V, "C'est même plus que je n'espérais. Merci de m'avoir écouté.", "기대한 것보다 더 좋은데요. 들어 주셔서 감사합니다."),
(V, "Bon, je ne vous embête plus. Vous avez du travail, je file.", "자, 더는 귀찮게 안 할게요. 일 많으실 텐데 가 보겠습니다."),
(H, "Assieds-toi cinq minutes. Ton café va refroidir.", "5분만 앉아. 커피 식겠다."),
(None, "Silence. Victor, la tasse à la main, regarde Hélène. Julien et Lucien ne bougent plus.", "침묵. 빅토르가 잔을 든 채 엘렌을 바라본다. 쥘리앵과 뤼시앵은 꼼짝도 하지 않는다."),
(V, "Pardon ? Vous venez de dire « assieds-toi » ?", "네? 방금 \"앉아\"라고 하셨어요?"),
(H, "J'ai dit quoi ? Non. Enfin... oui. C'est sorti tout seul.", "내가 뭐라고 했죠? 아니에요. 어... 맞아요. 저절로 나왔어요."),
(J, "Elle a dit « assieds-toi ». Lucien, tu as entendu ? Trois témoins.", "\"앉아\"라고 했어요. 뤼시앵, 들었죠? 증인이 셋이에요."),
(L, "Parfaitement entendu. Ma fille, c'est un tournant historique.", "똑똑히 들었지. 얘야, 역사적인 전환점이구나."),
(H, "Ne faites pas les malins, tous les deux. C'est la fatigue. Trois jours de réouverture.", "둘 다 잘난 척하지 마. 피곤해서 그래. 재개점 사흘째라고."),
(V, "Je prends la fatigue comme excuse. Mais si ça vous va, on pourrait continuer comme ça.", "피곤 탓으로 해 두죠. 그래도 괜찮으시면 이대로 계속해도 좋겠는데요."),
(H, "Ne pousse pas... Ne poussez pas. Enfin, on verra. On y va doucement.", "밀어붙이지 마... 밀어붙이지 마세요. 어쨌든 두고 봐요. 천천히 가요."),
(V, "Doucement, c'est un très bon rythme. Je m'assieds.", "천천히가 아주 좋은 속도예요. 앉을게요."),
(H, "Et je garde la bouteille. Mais ça ne veut rien dire, tu entends ?", "그리고 병은 내가 받을게요. 하지만 아무 의미 없어, 알겠어?"),
(V, "Parfaitement. Deux fois « tu » en une minute. Je le note dans mon carnet.", "물론이죠. 1분에 \"너\"를 두 번. 수첩에 적어 둘게요."),
(L, "À la bonne heure ! Julien, un second café. Et pour le savagnin, ce soir, après le service.", "잘됐군! 쥘리앵, 커피 한 잔 더. 그리고 사바냥은 오늘 밤 영업 끝나고."),
(V, "Alors c'est moi qui vous fais un coup de main demain. Je vous envoie mon pâtissier pour la Tatin.", "그럼 내일은 제가 도와드릴게요. 우리 파티셰를 보내서 타탱을 같이 만들게요."),
(H, "Ne marche pas sur mes plates-bandes, Victor. La Tatin, c'est moi.", "내 영역을 침범하지 마, 빅토르. 타탱은 내 거야."),
(None, "Victor boit son café, serre la main de Lucien, salue Julien et sort dans la rue froide.", "빅토르는 커피를 마시고 뤼시앵과 악수한 뒤 쥘리앵에게 인사하고 차가운 거리로 나간다."),
(J, "Il est parti. Alors, tu lui fais confiance ?", "갔네. 그래서 그 사람 믿어?"),
(H, "Je lui fais confiance pour le beurre. Pour le reste, on verra. C'est un début.", "버터는 믿어. 나머지는 두고 봐야지. 시작이긴 해."),
(L, "Qui sème la méfiance récolte la solitude, ma fille. Mais qui ne se méfie pas récolte des ennuis.", "의심을 뿌리면 외로움을 거두는 법이다, 얘야. 그래도 의심 없으면 골치만 거두지."),
(L, "Je suis là pour ça. Et Marthe, elle, aurait déjà mis le couvert pour lui.", "그러라고 내가 있는 거지. 그리고 마르트라면 벌써 저 친구 몫의 식탁을 차렸을 게다."),
(H, "Elle aurait dit : « Retournez travailler. »", "엄마라면 이렇게 말했겠죠. \"가서 일들 해.\""),
]

